import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  const E = (m) => fail(`error: line ${n}: ${m}`)
  if (w[0] === 'candidates') {
    if (cands !== null || ballots.length) E('candidates must be declared once, before any ballot')
    if (w.length < 2) E('expected candidates <name>...')
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!NAME.test(name)) E(`invalid candidate name ${name}`)
      if (seen.has(name)) E(`candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = w.slice(1)
  } else if (w[0] === 'ballot') {
    if (w.length < 3) E('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(w[1])) E('count must be a positive integer')
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (cands === null || !cands.includes(name)) E(`unknown candidate ${name}`)
      if (seen.has(name)) E(`candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    E(`unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const cont = new Set(cands)
const history = [] // Map name -> count per round
const out = []
let winner = null
for (;;) {
  const counts = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  let total = 0n
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => cont.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const k = history.length
  const order = [...cont].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    if (d !== 0n) return d > 0n ? 1 : -1
    return a < b ? -1 : a > b ? 1 : 0
  })
  out.push(`round ${k}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) break
  const top = order.find((c) => counts.get(c) * 2n > active)
  if (top !== undefined) {
    winner = top
    break
  }
  let min = null
  for (const c of cont) if (min === null || counts.get(c) < min) min = counts.get(c)
  let tied = [...cont].filter((c) => counts.get(c) === min)
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    const m = tied.reduce((a, c) => (history[r].get(c) < a ? history[r].get(c) : a), history[r].get(tied[0]))
    tied = tied.filter((c) => history[r].get(c) === m)
  }
  tied.sort()
  const gone = tied[tied.length - 1]
  cont.delete(gone)
  out.push(`eliminated ${gone}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.filter((l) => !l.startsWith('eliminated') || true).join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
EOF
